-- The failure bookkeeping of the race climate cache moves to its own non-state table, so a failed
-- refresh no longer writes a state model (ClimateCache) and no longer raises the data version.
-- Generated by `prisma migrate diff`, then edited: the CopyFailures step carries each cell's
-- back-off over before the redefine drops the two columns. A cache row that held only a failure
-- stays, empty and incomplete, and is read again as before.

-- CreateTable
CREATE TABLE "ClimateFailure" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "latE2" INTEGER NOT NULL,
    "lngE2" INTEGER NOT NULL,
    "monthDay" TEXT NOT NULL,
    "startHour" INTEGER NOT NULL,
    "windowHours" INTEGER NOT NULL,
    "failedAt" DATETIME NOT NULL,
    "lastError" TEXT
);

-- CopyFailures
INSERT INTO "ClimateFailure" ("id", "latE2", "lngE2", "monthDay", "startHour", "windowHours", "failedAt", "lastError")
SELECT "id", "latE2", "lngE2", "monthDay", "startHour", "windowHours", "failedAt", "lastError"
FROM "ClimateCache" WHERE "failedAt" IS NOT NULL;

-- RedefineTables
PRAGMA defer_foreign_keys=ON;
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_ClimateCache" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "latE2" INTEGER NOT NULL,
    "lngE2" INTEGER NOT NULL,
    "monthDay" TEXT NOT NULL,
    "startHour" INTEGER NOT NULL,
    "windowHours" INTEGER NOT NULL,
    "wbgtC" REAL,
    "samples" INTEGER NOT NULL DEFAULT 0,
    "yearsRead" INTEGER NOT NULL DEFAULT 0,
    "complete" BOOLEAN NOT NULL DEFAULT false,
    "fetchedAt" DATETIME
);
INSERT INTO "new_ClimateCache" ("complete", "fetchedAt", "id", "latE2", "lngE2", "monthDay", "samples", "startHour", "wbgtC", "windowHours", "yearsRead") SELECT "complete", "fetchedAt", "id", "latE2", "lngE2", "monthDay", "samples", "startHour", "wbgtC", "windowHours", "yearsRead" FROM "ClimateCache";
DROP TABLE "ClimateCache";
ALTER TABLE "new_ClimateCache" RENAME TO "ClimateCache";
CREATE UNIQUE INDEX "ClimateCache_latE2_lngE2_monthDay_startHour_windowHours_key" ON "ClimateCache"("latE2", "lngE2", "monthDay", "startHour", "windowHours");
PRAGMA foreign_keys=ON;
PRAGMA defer_foreign_keys=OFF;

-- CreateIndex
CREATE UNIQUE INDEX "ClimateFailure_latE2_lngE2_monthDay_startHour_windowHours_key" ON "ClimateFailure"("latE2", "lngE2", "monthDay", "startHour", "windowHours");
